const npcs=[];const npcColors=[0x9b6b5b,0x658078,0x927c4f];function makeNPC(x,z,index){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const cloth=mat(npcColors[index]),skin=mat([0xd4ad8b,0xe0bb97,0xc99572][index]),dark=mat(0x393e3b),hat=mat([0x576a54,0x986d4c,0x667c85][index]);const torso=new THREE.Mesh(new THREE.CylinderGeometry(.37,.48,1.05,8),cloth);torso.position.y=1.08;torso.castShadow=true;g.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.31,10,9),skin);head.position.y=1.91;head.castShadow=true;g.add(head);const hatMesh=new THREE.Mesh(new THREE.ConeGeometry(.39,.42,8),hat);hatMesh.position.y=2.28;hatMesh.castShadow=true;g.add(hatMesh);const brim=new THREE.Mesh(new THREE.CylinderGeometry(.42,.42,.09,10),hat);brim.position.y=2.12;g.add(brim);for(let side of [-1,1]){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.12,.14,.62,6),dark);leg.position.set(side*.2,.36,0);leg.castShadow=true;g.add(leg);const arm=new THREE.Mesh(new THREE.CylinderGeometry(.1,.13,.72,6),cloth);arm.position.set(side*.48,1.12,0);arm.rotation.z=side*.19;arm.castShadow=true;g.add(arm);const eye=new THREE.Mesh(new THREE.SphereGeometry(.035,6,6),mat(0x302a26));eye.position.set(side*.12,1.96,-.275);g.add(eye)}const satchel=new THREE.Mesh(new THREE.BoxGeometry(.28,.4,.18),mats.wood2);satchel.position.set(.4,.96,.2);satchel.rotation.z=-.2;g.add(satchel);g.userData={index,hp:3,maxHp:3,home:new THREE.Vector3(x,0,z),phase:Math.random()*6,hit:0,hitCooldown:0,seen:false,arms:g.children.filter(o=>o.geometry?.type==='CylinderGeometry'&&o.position.y>1)};npcs.push(g);return g}
