// Player, controls, equipment and valley folk
const ui={intro:document.querySelector('#intro'),start:document.querySelector('#start'),toast:document.querySelector('#toast'),quest:document.querySelector('.qsub'),fill:document.querySelector('#qfill'),health:document.querySelector('#healthBar'),healthNum:document.querySelector('#healthNum'),target:document.querySelector('#target'),targetName:document.querySelector('#targetName'),targetHp:document.querySelector('#targetHp'),cross:document.querySelector('#cross')};
let started=false,yaw=0,pitch=0,health=100,selected=0,attackAt=0,toastAt=0,hop=0,hopV=0,seenCount=0;const keys={},clock=new THREE.Clock(),raycaster=new THREE.Raycaster(),center=new THREE.Vector2(0,0),velocity=new THREE.Vector3();
const gearNames=['SABRE','WAND','LANTERN'],gear=[];
function makeGear(type){const g=new THREE.Group(),gold=mat(0xc69b58),steel=mat(0xc9d2c2),dark=mat(0x443b32),glow=new THREE.MeshStandardMaterial({color:type===1?0x91e5de:0xffc96d,emissive:type===1?0x3a9d9a:0xa85a20,emissiveIntensity:1.3,roughness:.3});
 const part=(geo,m,x,y,z,s)=>{let o=new THREE.Mesh(geo,m);o.position.set(x,y,z);if(s)o.scale.set(...s);g.add(o);return o};
 if(type===0){part(new THREE.CylinderGeometry(.045,.065,.37,8),dark,0,-.12,0);part(new THREE.SphereGeometry(.09,8,7),gold,0,-.3,0);let blade=part(new THREE.ConeGeometry(.085,.67,6),steel,0,.37,0);blade.rotation.x=Math.PI;part(new THREE.BoxGeometry(.37,.055,.09),gold,0,.04,0);}
 if(type===1){part(new THREE.CylinderGeometry(.045,.07,.63,8),dark,0,-.18,0);part(new THREE.CylinderGeometry(.065,.09,.12,8),gold,0,.06,0);part(new THREE.OctahedronGeometry(.15),glow,0,.3,0);}
 if(type===2){part(new THREE.TorusGeometry(.24,.045,7,12),gold,0,.02,0);part(new THREE.SphereGeometry(.18,10,8),glow,0,.02,0);part(new THREE.CylinderGeometry(.12,.12,.08,10),dark,0,-.22,0);}
 g.position.set(.42,-.42,-.76);g.rotation.set(-.1,-.12,0);camera.add(g);gear.push(g);
}
for(let i=0;i<3;i++)makeGear(i);scene.add(camera);camera.position.set(0,1.72,12);
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastAt=performance.now()+1900}
function choose(n){selected=(n+3)%3;gear.forEach((g,i)=>g.visible=i===selected);document.querySelectorAll('.slot').forEach((el,i)=>el.classList.toggle('active',i===selected));document.querySelector('#mswap').textContent=gearNames[selected];notify(`${gearNames[selected]} equipped`)}
function startGame(){if(started)return;started=true;ui.intro.classList.add('hidden');notify('Find the three wanderers nearby.');if(innerWidth>700)renderer.domElement.requestPointerLock?.()}
ui.start.addEventListener('click',startGame);
document.addEventListener('pointerlockchange',()=>{document.body.classList.toggle('locked',document.pointerLockElement===renderer.domElement)});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement&&started){yaw-=e.movementX*.0022;pitch=Math.max(-1.25,Math.min(1.25,pitch-e.movementY*.0022));camera.rotation.set(pitch,yaw,0)}});
renderer.domElement.addEventListener('click',()=>{if(started&&document.pointerLockElement!==renderer.domElement&&innerWidth>700)renderer.domElement.requestPointerLock?.();else useGear()});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Digit1')choose(0);if(e.code==='Digit2')choose(1);if(e.code==='Digit3')choose(2);if(e.code==='Space'&&started&&hop<=0)hopV=5.2;if(e.code==='KeyE')useGear()});window.addEventListener('keyup',e=>keys[e.code]=false);
document.querySelectorAll('.slot').forEach(el=>el.addEventListener('click',()=>choose(+el.dataset.slot)));
document.querySelector('#mswap').addEventListener('click',()=>choose(selected+1));document.querySelector('#mhit').addEventListener('click',useGear);
let stickX=0,stickY=0;const stick=document.querySelector('#stick');let stickPointer=null;
stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e)});function moveStick(e){let r=stick.getBoundingClientRect(),x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2),d=Math.hypot(x,y),max=r.width*.36;if(d>max){x*=max/d;y*=max/d}stickX=x/max;stickY=y/max;stick.style.transform=`translate(${x}px,${y}px)`}function resetStick(e){if(e.pointerId!==stickPointer)return;stickPointer=null;stickX=stickY=0;stick.style.transform=''}stick.addEventListener('pointerup',resetStick);stick.addEventListener('pointercancel',resetStick);
function aimedNPC(range=3.3){raycaster.setFromCamera(center,camera);raycaster.far=range;let hits=raycaster.intersectObjects(npcs.filter(n=>!n.userData.down).flatMap(n=>n.children),false);return hits.length?hits[0].object.parent.parent:null}
function useGear(){if(!started)return;let now=performance.now();if(now<attackAt)return;attackAt=now+(selected===1?700:selected===2?1100:480);let g=gear[selected];g.rotation.x=-.8;setTimeout(()=>{g.rotation.x=-.1},170);let reach=selected===0?3.4:selected===1?26:5.2,n=aimedNPC(reach);if(n){let d=camera.position.distanceTo(n.position);if(d<=reach){let data=n.userData;data.hp=Math.max(0,data.hp-1);data.hit=.32;data.stunned=1.05;let dir=n.position.clone().sub(camera.position).setY(0).normalize();n.position.addScaledVector(dir,selected===0?1.05:.45);n.rotation.y=Math.atan2(dir.x,dir.z);notify(data.hp?'A clean hit! The wanderer reels.':'The wanderer needs a moment...');if(data.hp===0){data.down=true;data.respawn=4.5;notify('They tumble back, then will be up again.')} } }else if(selected===2)notify('The lantern glows warmly.');}
function updateNPCs(dt,t){let nearest=null,nearestD=1e9;for(const n of npcs){const d=n.userData,p=n.position;d.phase+=dt;if(d.down){d.respawn-=dt;n.rotation.z=THREE.MathUtils.lerp(n.rotation.z,1.25,dt*4);if(d.respawn<=0){d.down=false;d.hp=3;p.copy(d.home);n.rotation.set(0,0,0);notify('A wanderer has recovered.')}continue}if(d.stunned>0)d.stunned-=dt;else{let tx=d.home.x+Math.sin(d.phase*.36+d.index*2)*2.1,tz=d.home.z+Math.cos(d.phase*.31+d.index)*2.2,dx=tx-p.x,dz=tz-p.z,l=Math.hypot(dx,dz);if(l>.12){p.x+=dx/l*dt*.48;p.z+=dz/l*dt*.48;n.rotation.y=Math.atan2(dx,dz)}}n.position.y=Math.sin(t*3+d.phase)*.045;n.children.forEach((c,i)=>{if(i===5||i===6)c.rotation.x=Math.sin(t*4+d.phase)*.12});let dist=camera.position.distanceTo(p);if(dist<nearestD){nearestD=dist;nearest=n}if(dist<5&&!d.seen){d.seen=true;seenCount++;ui.fill.style.width=`${seenCount/3*100}%`;ui.quest.textContent=seenCount>=3?'All three wanderers are found. Take your time.':`${3-seenCount} more wanderer${seenCount===2?'':'s'} to find.`;notify(['Mara: Lovely day for a slow walk, isn’t it?','Tovin: Keep an eye out for little lights in the grass.','Edda: The old market has seen a hundred summers.'][d.index])}}
 if(nearest&&nearestD<11){ui.target.classList.add('visible');ui.targetName.textContent=['MARA','TOVIN','EDDA'][nearest.userData.index];ui.targetHp.style.width=`${nearest.userData.hp/3*100}%`;ui.target.style.opacity=String(Math.max(.35,1-nearestD/17))}else ui.target.classList.remove('visible')}
function update(dt,t){if(!started)return;let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-stickY,right=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+stickX;if(stickPointer!==null){yaw-=stickX*dt*1.6;camera.rotation.y=yaw}let len=Math.hypot(forward,right);if(len>1){forward/=len;right/=len}let speed=keys.ShiftLeft?7.2:4.7;let dx=(Math.sin(yaw)*forward+Math.cos(yaw)*right)*speed*dt,dz=(-Math.cos(yaw)*forward+Math.sin(yaw)*right)*speed*dt;camera.position.x=THREE.MathUtils.clamp(camera.position.x+dx,-86,86);camera.position.z=THREE.MathUtils.clamp(camera.position.z+dz,-86,86);if(hop>0||hopV>0){hop+=hopV*dt;hopV-=15*dt;if(hop<0){hop=0;hopV=0}}camera.position.y=1.72+Math.max(0,hop);updateNPCs(dt,t);for(const p of pickups){p.g.rotation.y+=dt*.7;p.g.position.y=.65+Math.sin(t*2+p.phase)*.18;if(!p.got&&camera.position.distanceTo(p.g.position)<1.5){p.got=true;p.g.visible=false;notify('You found a little valley charm.');health=Math.min(100,health+10);ui.health.style.width=`${health}%`;ui.healthNum.textContent=health}}if(performance.now()>toastAt)ui.toast.classList.remove('show');}
function animate(){requestAnimationFrame(animate);let dt=Math.min(clock.getDelta(),.04),t=clock.elapsedTime;update(dt,t);lamps.forEach((l,i)=>l.intensity=1.05+Math.sin(t*2+i)*.12);renderer.render(scene,camera)}animate();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.5))});
</script></body></html>

